```js
// consumo de una API que devuelve [{ "id": 1, "title": "Todo" }]
async function cargarTodos() {
  try {
    const resp = await fetch('https://api.ejemplo.com/todos');
    if (!resp.ok) throw new Error(`HTTP ${resp.status}`);
    const datos = await resp.json(); // deserializa
    console.log(datos); // [{id:1, title:"Todo"}]
  } catch (e) {
    console.error('Error al cargar:', e);
  }
}
cargarTodos();
